import json
import sys
from unified_planning.shortcuts import *
from unified_planning.io import PDDLReader

def format_action(action_instance):
    name = action_instance.action.name
    params = []
    for arg in action_instance.actual_parameters:
        if arg.is_object_exp():
            params.append(arg.object().name)
        elif arg.is_constant():
            params.append(arg.constant().name)
        else:
            params.append(str(arg))
    return f"{name}({', '.join(params)})"

def solve_task(domain_path, problem_path, output_path):
    reader = PDDLReader()
    try:
        problem = reader.parse_problem(domain_path, problem_path)
    except Exception as e:
        print(f"Error parsing problem: {e}")
        return False

    # Use pyperplan as it was available
    with OneshotPlanner(name='pyperplan') as planner:
        result = planner.solve(problem)
        if result.status in (PlanGenerationResultStatus.SOLVED_SATISFIING, PlanGenerationResultStatus.SOLVED_OPTIMAL):
            plan = result.plan
            with open(output_path, 'w') as f:
                for action_instance in plan.actions:
                    f.write(format_action(action_instance) + "\n")
            return True
        else:
            print(f"Failed to solve: {result.status}")
            return False

if __name__ == "__main__":
    with open('problem.json', 'r') as f:
        tasks = json.load(f)

    for task in tasks:
        print(f"Solving {task['id']}...")
        success = solve_task(task['domain'], task['problem'], task['plan_output'])
        if success:
            print(f"Successfully solved {task['id']}")
        else:
            print(f"Failed to solve {task['id']}")
            # We don't exit(1) here to allow solving other tasks if any, 
            # but in this case we should probably try our best.
            # However, if one fails, we might want to know.
            pass

