import json
import sys
import re
from unified_planning.shortcuts import *
from unified_planning.io import PDDLReader
from unified_planning.engines import PlanGenerationResultStatus

def build_case_map(domain_path, problem_path):
    case_map = {}
    # Basic regex to find identifiers in PDDL
    pattern = re.compile(r'[a-zA-Z][a-zA-Z0-9_-]*')
    for path in [domain_path, problem_path]:
        with open(path, 'r') as f:
            content = f.read()
            for word in pattern.findall(content):
                low = word.lower()
                if low not in case_map or any(c.isupper() for c in word):
                    case_map[low] = word
    return case_map

def format_action(action_instance, case_map):
    name = action_instance.action.name
    name = case_map.get(name.lower(), name)
    params = []
    for arg in action_instance.actual_parameters:
        if arg.is_object_exp():
            obj_name = arg.object().name
            params.append(case_map.get(obj_name.lower(), obj_name))
        elif arg.is_constant():
            const_name = arg.constant().name
            params.append(case_map.get(const_name.lower(), const_name))
        else:
            params.append(str(arg))
    return f"{name}({', '.join(params)})"

def solve_task(domain_path, problem_path, output_path):
    reader = PDDLReader()
    try:
        problem = reader.parse_problem(domain_path, problem_path)
